head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods20000";
scwin.editor = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("integSrchNm") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldods20000: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.editor =new Dext5editor("dext5editor1"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldods20000' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods20000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_integsrchList_oncellclick
 * @description grd_integsrchList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_integsrchList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_integsrchList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_integsrchList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: previewPopOpen (조건 미해석) */
        scwin.search_detail(r["integSrchNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_integsrchList.oncellclick' });
    }
};

/**
 * @method
 * @name input_46_onclick
 * @description 「등록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_46_onclick = function(e){
    try {
        scwin.regBzExpl()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20000.input_46_onclick' }); }
};

/**
 * @method
 * @name input_51_onclick
 * @description 「등록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_51_onclick = function(e){
    try {
        scwin.regMktactRsn()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20000.input_51_onclick' }); }
};

/**
 * @method
 * @name input_55_onclick
 * @description 「등록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_55_onclick = function(e){
    try {
        scwin.regMcc()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20000.input_55_onclick' }); }
};

/**
 * @method
 * @name btn_regAll_onclick
 * @description 「전체등록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_regAll_onclick = function(e){
    try {
        scwin.regAll()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20000.btn_regAll_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search_detail
 * @description search detail 처리
 * @param {*} integSrchNo integSrchNo
 * @returns {void}
 * @hidden N
 */
scwin.search_detail = function (integSrchNo) {
    const curIntegSrchNo = $('#integSrchNo').val();
    if (curIntegSrchNo === integSrchNo) {
        return;
    }
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "searchIntegsrchList") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#integSrchNo').val(integSrchNo);
    $('#headerKeywrdForm')[0].submit();
    blockLoading();
};

/**
 * @method
 * @name regBzExpl
 * @description reg Bz Expl 처리
 * @returns {void}
 * @hidden N
 */
scwin.regBzExpl = function () {
    const a = DEXT5.getBodyValue("dext5editor1");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('bzExplContn', a) : console.warn('[sdd] hiddenStore 부재: bzExplContn'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "insertBzExpl") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#headerKeywrdForm')[0].submit();
};

/**
 * @method
 * @name regMcc
 * @description reg Mcc 처리
 * @returns {void}
 * @hidden N
 */
scwin.regMcc = function () {
    const a = DEXT5.getBodyValue("dext5editor3");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('mccContn', a) : console.warn('[sdd] hiddenStore 부재: mccContn'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "insertMcc") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#headerKeywrdForm')[0].submit();
};

/**
 * @method
 * @name regMktactRsn
 * @description reg Mktact Rsn 처리
 * @returns {void}
 * @hidden N
 */
scwin.regMktactRsn = function () {
    const a = DEXT5.getBodyValue("dext5editor2");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('mktactRsnContn', a) : console.warn('[sdd] hiddenStore 부재: mktactRsnContn'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "insertMktactRsn") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#headerKeywrdForm')[0].submit();
};

/**
 * @method
 * @name regAll
 * @description reg All 처리
 * @returns {void}
 * @hidden N
 */
scwin.regAll = function () {
    let a = DEXT5.getBodyValue("dext5editor2");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('mktactRsnContn', a) : console.warn('[sdd] hiddenStore 부재: mktactRsnContn'));
    a = DEXT5.getBodyValue("dext5editor3");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('mccContn', a) : console.warn('[sdd] hiddenStore 부재: mccContn'));
    a = DEXT5.getBodyValue("dext5editor1");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('bzExplContn', a) : console.warn('[sdd] hiddenStore 부재: bzExplContn'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "insertAll") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#headerKeywrdForm')[0].submit();
};

/**
 * @method
 * @name dext_editor_loaded_event
 * @description dext editor loaded event 처리
 * @param {*} editor editor
 * @returns {void}
 * @hidden N
 */
scwin.dext_editor_loaded_event = function (editor) {
    if (editor.ID === "dext5editor1") {
        DEXT5.setBodyValue(dma_hiddenStore.get("bzExplContn"), editor.ID);
    } else {
        if (editor.ID === "dext5editor3") {
            DEXT5.setBodyValue(dma_hiddenStore.get("mccContn"), editor.ID);
            setTimeout(function(){ scrollTo(0,0); }, 500);
        } else {
            if (editor.ID === "dext5editor2") {
                DEXT5.setBodyValue(dma_hiddenStore.get("mktactRsnContn"), editor.ID);
            }
        }
    }
};
